#include <vector>

class Solution {
public:
    std::vector<std::vector<int>> aggregateTimeSeries(std::vector<std::vector<int>>& series1, std::vector<std::vector<int>>& series2) {
        int i = 0, j = 0;
        int m = series1.size(), n = series2.size();
        std::vector<std::vector<int>> res;
        while (i < m && j < n) {
            if (series1[i][0] == series2[j][0]) {
                res.push_back({series1[i][0], series1[i][1] + series2[j][1]});
                i++; j++;
            } else if (series1[i][0] < series2[j][0]) {
                res.push_back(series1[i++]);
            } else {
                res.push_back(series2[j++]);
            }
        }
        while (i < m) res.push_back(series1[i++]);
        while (j < n) res.push_back(series2[j++]);
        return res;
    }
};

import java.util.*;

class Solution {
    public int[][] aggregateTimeSeries(int[][] series1, int[][] series2) {
        int i = 0, j = 0;
        int m = series1.length, n = series2.length;
        List<int[]> res = new ArrayList<>();
        while (i < m && j < n) {
            if (series1[i][0] == series2[j][0]) {
                res.add(new int[]{series1[i][0], series1[i][1] + series2[j][1]});
                i++; j++;
            } else if (series1[i][0] < series2[j][0]) {
                res.add(series1[i++]);
            } else {
                res.add(series2[j++]);
            }
        }
        while (i < m) res.add(series1[i++]);
        while (j < n) res.add(series2[j++]);
        return res.toArray(new int[res.size()][]);
    }
}

